$title='Product Editor';require __DIR__.'/inc/header.php';$pdo=db();$id=(int)get('id',0);$creating=!$id;$edit=null;if($id){$st=$pdo->prepare('SELECT * FROM products WHERE id=?');$st->execute([$id]);$edit=$st->fetch();if(!$edit){flash('error','Product not found.');redirect('/admin/products.php');}}$edit=$edit?:['id'=>0,'name'=>'','sku'=>'','brand'=>'PAROKO','category_id'=>'','price'=>'','compare_price'=>'','short_description'=>'','description'=>'','warranty'=>'','status'=>1,'featured'=>0,'is_new'=>0,'is_best_seller'=>0,'slug'=>''];$cats=$pdo->query('SELECT * FROM categories WHERE status=1 ORDER BY type,sort_order')->fetchAll();$images=$id?$pdo->query('SELECT * FROM product_images WHERE product_id='.(int)$id.' ORDER BY sort_order,id')->fetchAll():[];$files=$id?$pdo->query('SELECT * FROM product_files WHERE product_id='.(int)$id.' ORDER BY id DESC')->fetchAll():[];$variant=null;if($id){$st=$pdo->prepare('SELECT * FROM variants WHERE product_id=? ORDER BY id LIMIT 1');$st->execute([$id]);$variant=$st->fetch();}$variant=$variant?:['id'=>0,'sku'=>($edit['sku']?$edit['sku'].'-DEFAULT':''),'color'=>'Black','size'=>'M','stock'=>10,'low_stock_threshold'=>5];$msg='';
if(is_post()){verify_csrf();$action=(string)post('action','');if($action==='remove_image'){$pdo->prepare('DELETE FROM product_images WHERE id=? AND product_id=?')->execute([(int)post('image_id'),$id]);flash('success','Gallery image removed.');redirect('/admin/product-edit.php?id='.$id);}if($action==='delete_file'){$st=$pdo->prepare('SELECT stored_path FROM product_files WHERE id=? AND product_id=?');$st->execute([(int)post('file_id'),$id]);$f=$st->fetch();if($f&&is_file($f['stored_path']))@unlink($f['stored_path']);$pdo->prepare('DELETE FROM product_files WHERE id=? AND product_id=?')->execute([(int)post('file_id'),$id]);flash('success','Protected file deleted.');redirect('/admin/product-edit.php?id='.$id);}if($action==='save'){$name=trim((string)post('name'));$sku=trim((string)post('sku'));$cat=(int)post('category_id');$price=(float)post('price');$compare=post('compare_price')!==''?(float)post('compare_price'):null;$desc=(string)post('description');$short=trim((string)post('short_description'));$brand=trim((string)post('brand','PAROKO'));$warranty=trim((string)post('warranty'));$status=post('status')==='1'?1:0;$featured=post('featured')?1:0;$new=post('is_new')?1:0;$best=post('is_best_seller')?1:0;try{if($creating){$slug=slugify($name).'-'.strtolower(bin2hex(random_bytes(2)));$pdo->prepare('INSERT INTO products(category_id,brand,name,slug,sku,description,short_description,price,compare_price,warranty,status,featured,is_new,is_best_seller) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$cat,$brand,$name,$slug,$sku,$desc,$short,$price,$compare,$warranty,$status,$featured,$new,$best]);$id=(int)$pdo->lastInsertId();}else{$pdo->prepare('UPDATE products SET category_id=?,brand=?,name=?,sku=?,description=?,short_description=?,price=?,compare_price=?,warranty=?,status=?,featured=?,is_new=?,is_best_seller=? WHERE id=?')->execute([$cat,$brand,$name,$sku,$desc,$short,$price,$compare,$warranty,$status,$featured,$new,$best,$id]);}$variantId=(int)post('variant_id',0);$variantSku=trim((string)post('variant_sku',$sku.'-DEFAULT'));$variantColor=trim((string)post('variant_color','Black'));$variantSize=trim((string)post('variant_size','M'));$variantStock=(int)post('stock',10);$low=(int)post('low_stock_threshold',5);if($variantId)$pdo->prepare('UPDATE variants SET sku=?,color=?,size=?,price=?,compare_price=?,stock=?,low_stock_threshold=? WHERE id=? AND product_id=?')->execute([$variantSku,$variantColor,$variantSize,$price,$compare,$variantStock,$low,$variantId,$id]);else $pdo->prepare('INSERT INTO variants(product_id,sku,color,size,price,compare_price,stock,low_stock_threshold,status) VALUES(?,?,?,?,?,?,?,?,1)')->execute([$id,$variantSku,$variantColor,$variantSize,$price,$compare,$variantStock,$low]);if(!empty($_FILES['gallery']['name'][0])){foreach($_FILES['gallery']['name'] as $i=>$n){$f=['name'=>$n,'type'=>$_FILES['gallery']['type'][$i],'tmp_name'=>$_FILES['gallery']['tmp_name'][$i],'error'=>$_FILES['gallery']['error'][$i],'size'=>$_FILES['gallery']['size'][$i]];$u=save_public_upload($f,['jpg','jpeg','png','webp','gif','svg'],12000000,'products');$mx=(int)$pdo->query('SELECT COALESCE(MAX(sort_order),0) FROM product_images WHERE product_id='.(int)$id)->fetchColumn();$pdo->prepare('INSERT INTO product_images(product_id,image,sort_order) VALUES(?,?,?)')->execute([$id,$u['path'],$mx+1]);}}if(isset($_FILES['download_file'])&&($_FILES['download_file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$f=save_private_download($_FILES['download_file']);$pdo->prepare('INSERT INTO product_files(product_id,filename,stored_path,mime,size) VALUES(?,?,?,?,?)')->execute([$id,$f['filename'],$f['stored_path'],$f['mime'],$f['size']]);}flash('success',$creating?'Product created.':'Product updated.');redirect('/admin/product-edit.php?id='.$id);}catch(Throwable $e){$msg=$e->getMessage();}}}
