ue="<?=e((string)$variant['stock'])?>" placeholder="Stock"><input name="low_stock_threshold" type="number" value="<?=e((string)$variant['low_stock_threshold'])?>" placeholder="Low stock threshold" class="col-span-2"></div></div><div class="rounded-2xl border p-4"><div class="font-black">Gallery Upload</div><div class="text-xs text-slate-500 mt-1">Multiple file selection. No image URL input.</div><input type="file" name="gallery[]" multiple accept="image/*" class="mt-3 w-full"></div><div class="grid grid-cols-3 sm:grid-cols-5 gap-2"><?php foreach($images as $im):?><div class="relative"><img src="<?=e($im['image'])?>" class="aspect-square w-full object-cover rounded-xl border"><form method="post" class="absolute top-1 right-1"><?=csrf_input()?><input type="hidden" name="action" value="remove_image"><input type="hidden" name="image_id" value="<?=$im['id']?>"><button class="w-7 h-7 bg-rose-600 text-white rounded-full">×</button></form></div><?php endforeach;?></div></div><div class="space-y-4"><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black mb-3">Visibility</div><div class="space-y-3 text-sm"><label class="flex items-center gap-2"><input type="checkbox" name="featured" <?=$edit['featured']?'checked':''?>> Featured</label><label class="flex items-center gap-2"><input type="checkbox" name="is_new" <?=$edit['is_new']?'checked':''?>> New Arrival</label><label class="flex items-center gap-2"><input type="checkbox" name="is_best_seller" <?=$edit['is_best_seller']?'checked':''?>> Best Seller</label><select name="status" class="w-full"><option value="1" <?=$edit['status']?'selected':''?>>Published</option><option value="0" <?=!$edit['status']?'selected':''?>>Hidden</option></select></div></div><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black mb-3">Protected Digital ZIP</div><div class="text-xs text-slate-500">Stored outside public uploads. Buyer authorization is checked before download.</div><input type="file" name="download_file